import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Shield, Terminal, History, User, LogOut, Menu, X } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '16px 32px',
      backgroundColor: 'var(--bg-secondary)',
      borderBottom: '1px solid var(--border-glow)',
      position: 'sticky',
      top: 0,
      zIndex: 1000
    }}>
      <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '12px', textDecoration: 'none' }}>
        <Shield size={28} color="var(--accent-cyan)" />
        <span style={{ fontSize: '18px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
          NET_SENTINEL // SOC
        </span>
      </Link>

      {/* Desktop Menu */}
      <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }} className="desktop-menu">
        <Link to="/" className="cyber-button" style={{ padding: '8px 14px', fontSize: '13px' }}>HOME</Link>
        <Link to="/dashboard" className="cyber-button" style={{ padding: '8px 14px', fontSize: '13px' }}>
          <Terminal size={14} /> SCANNER
        </Link>
        <Link to="/history" className="cyber-button" style={{ padding: '8px 14px', fontSize: '13px' }}>
          <History size={14} /> LOGS
        </Link>

        {user ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginLeft: '10px' }}>
            <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '13px' }}>
              [{user.name}]
            </span>
            <button className="cyber-button" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '6px 10px' }}>
              <LogOut size={14} />
            </button>
          </div>
        ) : (
          <Link to="/login" className="cyber-button" style={{ padding: '8px 16px', fontSize: '13px' }}>
            <User size={14} /> SIGN UP / LOGIN
          </Link>
        )}
      </div>
    </nav>
  );
}
